const $=s=>document.querySelector(s), uuid=()=>crypto.randomUUID();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',athletes:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',programs:'M8 3H5a2 2 0 0 0-2 2v16l7-4 7 4V5a2 2 0 0 0-2-2h-3 M9 3h3v5H9z',workouts:'M6 5v14 M3 8v8 M18 5v14 M21 8v8 M6 12h12',progress:'M3 3v18h18 M7 14l4-5 4 3 6-8',messages:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5z',nutrition:'M8 2v7 M4 2v7a4 4 0 0 0 8 0V2 M8 13v9 M20 2c-5 3-5 10 0 10V2z M20 12v10',checkins:'M9 3H5a2 2 0 0 0-2 2v15a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-4 M9 2h6v4H9z M8 13l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 4 4 1 2 5-3 3v4l-5 3-3-2-4 1-4-4 1-4-2-4 3-4z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12l4 4L19 6',clock:'M12 8v4l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',logout:'M9 5H4v14h5 M10 12h11 M17 8l4 4-4 4',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.workouts}"/></svg>`;
const flame=`<svg viewBox="0 0 40 48" fill="currentColor" aria-hidden="true"><path d="M24 1c3 13-17 17-16 30 1 17 26 19 27 1 0-7-5-11-5-17-6 3-5 10-9 12-6-5 7-13 3-26Z"/></svg>`;
const num=v=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:1});
const initials=n=>String(n||'Athlete').split(' ').slice(0,2).map(v=>v[0]).join('').toUpperCase();
const when=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
let mode=config.firebase?'firebase':'demo', api=null, user=null, account='demo', data=null, role='coach', route='dashboard', selectedRelation='', filter='all', draft=null, draftWorkout=0, syncing=false, authGeneration=0, messageDraft='';
let relationSubscriptions=new Map(), relationQueries=new Map(), persistChain=Promise.resolve();
const modal=$('#modal');
const store=()=>{const key=account, snapshot=structuredClone(data);persistChain=persistChain.catch(()=>{}).then(()=>saveAccount(key,snapshot));return persistChain;};
const currentUid=()=>mode==='demo'?(role==='coach'?'demo-coach':'demo-athlete-0'):user?.uid;
const activeRelations=()=>data.relationships.filter(r=>r.status==='active' && (role==='coach'?r.coachId===currentUid():r.athleteId===currentUid()));
const mineSessions=()=>data.sessions.filter(s=>role==='coach'?activeRelations().some(r=>r.id===s.relationshipId):s.athleteId===currentUid());
const mySchedule=()=>data.scheduled.filter(s=>role==='coach'?activeRelations().some(r=>r.id===s.relationshipId):s.athleteId===currentUid());
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function badge(label,tone=''){return `<span class="badge ${tone}"><i class="dot"></i>${esc(label)}</span>`;}
function button(label,action,id='',primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;}
function empty(message,action=''){return `<div class="empty">${icon('workouts')}<p>${message}</p>${action}</div>`;}
function title(name,sub,action=''){return `<div class="page-title"><div><h1>${name}</h1><p>${sub}</p></div>${action}</div>`;}
function person(r,i=0){return `<div class="person"><div class="avatar a${i%3}">${esc(initials(r.athleteName))}</div><div><strong>${esc(r.athleteName)}</strong><small>Connected ${when(r.startedAt)}</small></div></div>`;}
function metric(label,value,note,name='progress'){return `<div class="card stat"><div class="row">${label}${icon(name)}</div><div class="metric">${value}</div><small>${note}</small></div>`;}
function getRelation(){const rels=activeRelations();return rels.find(r=>r.id===selectedRelation)||rels[0];}
function completed(){return mineSessions().filter(s=>s.status==='completed');}
function weekly(){const cut=Date.now()-7*86400000;return completed().filter(s=>s.completedAt>=cut);}
function render(){
  if(!data) return;
  if(mode==='firebase' && !user){renderLogin();return;}
  const coach=role==='coach', nav=[['dashboard','Overview'],...(coach?[['athletes','Athletes'],['programs','Programs']]:[]),['workouts','Workouts'],['progress','Progress'],['messages','Messages'],['nutrition','Nutrition'],['checkins','Check-ins'],['settings','Settings']];
  if(!nav.some(([key])=>key===route))route='dashboard';
  const displayName=mode==='demo'?(coach?'Your Coach':'Alex Morgan'):(data.profile?.displayName || user.displayName || 'Athlete');
  const name=nav.find(([key])=>key===route)[1];
  const state=mode==='demo'?badge('Sample · device only','amber'):!navigator.onLine?badge('Offline · saved on device','amber'):data.outbox.length?badge(`${data.outbox.length} waiting to sync`,'amber'):badge('Firebase connected');
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="coaching.html">${flame}<div><strong>FLAMES</strong><small>COACHING</small></div></a><div class="nav-label">${coach?'COACH WORKSPACE':'YOUR TRAINING'}</div><nav class="nav" aria-label="Main navigation">${nav.map(([key,label])=>`<button data-route="${key}" class="${key===route?'active':''}" ${key===route?'aria-current="page"':''}>${icon(key)}${label}${key==='checkins' && data.checkIns.filter(c=>c.status==='submitted').length?`<span class="count">${data.checkIns.filter(c=>c.status==='submitted').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('workouts')} Training, connected.<p>Better programming.<br>Stronger together.</p></div><div class="user"><div class="avatar">${esc(initials(displayName))}</div><div><strong>${esc(displayName)}</strong><small>${coach?'Coach workspace':'Athlete workspace'}</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="crumb">Workspace <span>/ &nbsp; ${name}</span></div><div class="top-actions"><span class="date-chip">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span>${state}<select class="role-select" id="role" aria-label="Workspace">${mode==='demo'||data.coachAccount?.status==='active'?`<option value="coach" ${coach?'selected':''}>Coach view</option>`:''}<option value="athlete" ${!coach?'selected':''}>Athlete view</option></select></div></header><main id="main" tabindex="-1">${({dashboard:dashboard,athletes:athletes,programs:programs,workouts:workouts,progress:progress,messages:messages,nutrition:nutrition,checkins:checkins,settings:settings})[route]()}</main></div>`;
}
function dashboard(){
  const coach=role==='coach', rels=activeRelations(), done=weekly(), volume=done.reduce((n,s)=>n+totals(s).volumeKg,0), pending=data.checkIns.filter(c=>c.status==='submitted' && rels.some(r=>r.id===c.relationshipId));
  return title(coach?'Every rep. Every athlete.':'Your next chapter starts here.',coach?'A clear view of your athletes, their training, and what needs you next.':'Your program, your progress, and your coach. All in one place.',coach?`<button class="btn primary" data-action="invite">${icon('plus')} Invite athlete</button>`:button('Start a workout','quick-workout','',true))+
  `<div class="grid metrics">${metric(coach?'Active athletes':'This week’s workouts',coach?rels.length:done.length,coach?'Connected coaching relationships':'Completed in the last 7 days','athletes')}${metric('Workouts completed',done.length,'Last 7 days','workouts')}${metric('Training volume',`${num(volume)}<span style="font-size:13px;color:var(--muted);margin-left:5px">kg</span>`,'Completed sets · last 7 days','progress')}${metric(coach?'Check-ins to review':'Upcoming workouts',coach?pending.length:mySchedule().filter(s=>s.status==='planned').length,coach?'Ready for your feedback':'Available in your program','checkins')}</div>`+
  `<div class="welcome"><div><div class="eyebrow" style="color:#819ddb;margin-bottom:9px">${coach?'BUILT AROUND THEIR PROGRESS':'TRAIN WITH INTENTION'}</div><h2>${coach?'Small adjustments.<br>Stronger outcomes.':'Show up. Log the work.<br>Build your momentum.'}</h2><p>${coach?'Your next great coaching decision starts with a conversation.':'Your completed workouts stay yours, as your program evolves.'}</p></div><span class="mark">↗</span>${button(coach?'Build a program':'View workouts',coach?'new-program':'go-workouts')}</div>`+
  `<div class="grid two-col"><section class="card"><div class="card-head"><h2>${coach?'Your athletes':'Your training week'}</h2><button class="btn small ghost" data-route="${coach?'athletes':'workouts'}">View all ${icon('arrow')}</button></div>${coach?athleteTable(rels):scheduleList(mySchedule().slice(0,3))}</section><section class="card"><div class="card-head"><h2>Recent activity</h2><small>Training updates</small></div>${activity()}</section></div><div class="grid two-col section-space"><section class="card"><div class="card-head"><h2>Weekly training volume</h2>${badge('Last 7 days','gray')}</div>${chart()}</section><section class="card pad"><div class="eyebrow">NEXT UP</div><h2 style="margin:12px 0">${coach?'Keep the feedback loop moving.':'Make consistency your advantage.'}</h2><p class="muted" style="font-size:12px;margin:12px 0 22px">${coach?'Review athlete check-ins and leave a clear, useful next step.':'Log your meals, check in with your coach, and see the work add up.'}</p>${button(coach?'Review check-ins':'Open check-ins','go-checkins')}</section></div>${mode==='demo'?'<p class="footer-note">Sample workspace · All people and training records shown here are fictional. Changes are saved only in this browser.</p>':''}`;
}
function athleteTable(rels){return !rels.length?empty('Your roster starts with one invitation.',button('Invite an athlete','invite','',true)):`<div class="table-wrap"><table><thead><tr><th>Athlete</th><th>Last workout</th><th>This week</th><th></th></tr></thead><tbody>${rels.map((r,i)=>{const ss=data.sessions.filter(s=>s.athleteId===r.athleteId&&s.status==='completed').sort((a,b)=>b.completedAt-a.completedAt), recent=ss.filter(s=>s.completedAt>Date.now()-7*86400000).length;return `<tr><td>${person(r,i)}</td><td>${ss[0]?when(ss[0].completedAt):'No workout yet'}</td><td>${recent} sessions</td><td><button class="btn small ghost" data-action="athlete-detail" data-id="${esc(r.id)}">View ${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function athletes(){return title('Your athletes','Good coaching starts with knowing where each person is.',`<button class="btn primary" data-action="invite">${icon('plus')} Invite athlete</button>`)+`<section class="card"><div class="card-head"><h2>Active connections</h2>${badge(`${activeRelations().length} athletes`,'blue')}</div>${athleteTable(activeRelations())}</section>`+(!data.invitations.length?'':`<section class="card section-space"><div class="card-head"><h2>Invitations created on this device</h2></div>${data.invitations.map(i=>`<div class="checkin row between wrap"><div><strong>${esc(i.email)}</strong><p>Expires ${when(i.expiresAt)} · ${esc(i.status)}</p></div>${i.status==='pending'?button('Revoke','revoke-invite',i.inviteId):''}</div>`).join('')}</section>`);}
function activity(){const list=completed().sort((a,b)=>b.completedAt-a.completedAt).slice(0,4);return !list.length?empty('Completed workouts will appear here.'):`<div class="activity">${list.map(s=>{const r=data.relationships.find(r=>r.id===s.relationshipId);return `<div class="activity-item"><span class="activity-icon">${icon('check')}</span><div><p><strong>${esc(role==='coach'?r?.athleteName || 'Athlete':'You')}</strong> completed a workout</p><small>${esc(s.name)} · ${when(s.completedAt)}</small></div></div>`;}).join('')}</div>`;}
function chart(){const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const key=dateKey(date);return {label:date.toLocaleDateString(undefined,{weekday:'short'}),value:completed().filter(s=>s.localDate===key).reduce((n,s)=>n+totals(s).volumeKg,0)};}), max=Math.max(1,...days.map(d=>d.value));return `<div class="chart" role="img" aria-label="Daily training volume in kilograms: ${days.map(d=>`${d.label} ${num(d.value)}`).join(', ')}">${days.map(d=>`<div class="chart-col"><small>${d.value?num(d.value):'—'}</small><i style="height:${Math.max(2,d.value/max*110)}px"></i><span>${d.label}</span></div>`).join('')}</div><div class="chart-caption">Volume = completed reps × load in kg. Bodyweight load is not estimated.</div>`;}
function programs(){const ps=data.programs.filter(p=>p.coachId===currentUid());return title('Built with intention.','Create repeatable training. Publish a version. Make it personal.',`<button class="btn primary" data-action="new-program">${icon('plus')} New program</button>`)+`<div class="grid program-grid">${ps.map((p,i)=>`<section class="card"><div class="program-cover">${icon('workouts')}<span>0${i+1}</span></div><div class="program-body"><div class="row between"><h2>${esc(p.name)}</h2></div><p>${esc(p.description || 'Your next training block.')}</p><div class="program-meta"><span>${p.workouts.length} workouts</span><span>Revision ${p.revision}</span>${badge(p.status,p.status==='published'?'':'gray')}</div><div class="row wrap">${button('Edit program','edit-program',p.id)}${p.publishedVersionId?button('Assign','assign',p.id,true):''}</div></div></section>`).join('') || `<section class="card">${empty('Create your first program to start building a training block.',button('Build a program','new-program','',true))}</section>`}</div><p class="footer-note">Published versions are immutable. Assignments receive a copy; edits never replace an active workout.</p>`;}
function scheduleList(list){return !list.length?empty('No assigned workouts yet. Your coach’s program will appear here.',role==='athlete'?button('Start a personal workout','quick-workout'):button('Build a program','new-program')):list.sort((a,b)=>a.scheduledLocalDate.localeCompare(b.scheduledLocalDate)).map(s=>`<div class="checkin row between"><div><div class="eyebrow">${esc(s.scheduledLocalDate)} · ${esc(s.programVersionId || 'Personal')}</div><h3 style="margin-top:8px">${esc(s.workout.name)}</h3><p style="margin:6px 0 0">${s.workout.exercises.length} exercises · ${s.workout.exercises.reduce((n,e)=>n+e.sets.length,0)} sets</p></div>${role==='athlete' && s.status==='planned'?button('Start workout','start-workout',s.id,true):badge(s.status,s.status==='completed'?'':'gray')}</div>`).join('');}
function workouts(){
  const session=data.sessions.find(s=>s.id===data.activeSessionId && s.athleteId===currentUid() && s.status==='inProgress');
  if(session && role==='athlete')return activeWorkout(session);
  return title(role==='coach'?'Training in motion.':'Your workouts. Your momentum.',role==='coach'?'Assigned sessions and completed training, in one place.':'Follow your coach’s plan or start a personal session.',role==='athlete'?button('Personal workout','quick-workout','',true):'')+`<div class="pill-tabs"><button class="${filter!=='history'?'active':''}" data-filter="all">Upcoming</button><button class="${filter==='history'?'active':''}" data-filter="history">History</button></div><section class="card">${filter==='history'?historyTable():scheduleList(mySchedule().filter(s=>s.status==='planned'))}</section>`;
}
function historyTable(){const ss=completed().sort((a,b)=>b.completedAt-a.completedAt);return !ss.length?empty('Your completed workouts will appear here.'):`<div class="table-wrap"><table><thead><tr><th>Workout</th><th>Date</th><th>Sets</th><th>Volume</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.localDate)}</td><td>${totals(s).sets}</td><td>${num(totals(s).volumeKg)} kg</td></tr>`).join('')}</tbody></table></div>`;}
function activeWorkout(s){const done=totals(s).sets,total=s.exercises.reduce((n,e)=>n+e.sets.length,0);return title(esc(s.name),`${done} of ${total} sets complete · ${num(totals(s).volumeKg)} kg moved`,button('Finish workout','finish-workout',s.id,true))+`<div class="notice">Your session keeps the prescription you started with. Each checked set is saved on this device${mode==='firebase'?' and queued for Firebase sync':''}.</div><section class="card">${s.exercises.map((e,ei)=>`<div class="exercise"><div class="exercise-head"><span class="exercise-no">${String(ei+1).padStart(2,'0')}</span><h2>${esc(e.name)}</h2></div><div class="set-grid"><label>SET</label><label>LOAD · KG</label><label>REPS</label><label>DONE</label></div>${e.sets.map((set,si)=>`<div class="set-grid"><span class="muted">${si+1}</span><input type="number" min="0" max="1000" step="0.5" aria-label="${esc(e.name)} set ${si+1} load in kg" value="${set.weightKg}" data-session-field="weightKg" data-ex="${ei}" data-set="${si}"><input type="number" min="0" max="1000" step="1" aria-label="${esc(e.name)} set ${si+1} reps" value="${set.reps}" data-session-field="reps" data-ex="${ei}" data-set="${si}"><button class="done-btn ${set.done?'done':''}" aria-label="${set.done?'Uncheck':'Complete'} ${esc(e.name)} set ${si+1}" aria-pressed="${set.done}" data-action="toggle-set" data-ex="${ei}" data-set="${si}">${icon('check')}</button></div>`).join('')}</div>`).join('')}</section><p class="footer-note">Changes save to this account’s device storage. Export a backup from Settings before clearing browser data.</p>`;}
function progress(){const ss=completed(), allSets=ss.reduce((n,s)=>n+totals(s).sets,0),vol=ss.reduce((n,s)=>n+totals(s).volumeKg,0);return title('The work adds up.','A clear record of what you’ve completed. Every session counts.')+`<div class="grid metrics">${metric('Completed sessions',ss.length,'Loaded workout history','workouts')}${metric('Working sets',allSets,'Checked sets only','checkins')}${metric('Total volume',num(vol)+' kg','Logged external load','progress')}${metric('This week',weekly().length,'Last 7 days','clock')}</div><section class="card"><div class="card-head"><h2>Training volume</h2><small>Last 7 days</small></div>${chart()}</section><section class="card section-space"><div class="card-head"><h2>Workout history</h2><small>Accepted records and pending device changes</small></div>${historyTable()}</section>`;}
function messages(){const rels=activeRelations(), r=getRelation();return title('Stay in the conversation.','Feedback, questions, and the small details that make coaching work.')+`<section class="card messages-layout"><div class="conversations">${rels.map((r,i)=>`<button class="conversation ${r.id===getRelation()?.id?'active':''}" data-action="conversation" data-id="${esc(r.id)}"><span class="avatar a${i%3}">${esc(initials(role==='coach'?r.athleteName:r.coachName))}</span><span>${esc(role==='coach'?r.athleteName:r.coachName)}<small>Coaching conversation</small></span></button>`).join('')}</div>${!r?empty('Connect with a coach or athlete to start a conversation.'):`<div class="thread"><div class="thread-head"><h3>${esc(role==='coach'?r.athleteName:r.coachName)}</h3><small>Active coaching connection</small></div><div class="bubbles">${data.messages.filter(m=>m.relationshipId===r.id).sort((a,b)=>a.createdAt-b.createdAt).map(m=>`<div class="bubble ${m.senderId===currentUid()?'mine':''}">${esc(m.text)}<small>${new Date(m.createdAt).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}${m.pending?' · Pending':''}</small></div>`).join('')||'<p class="muted">Start with a hello.</p>'}</div><form class="compose" id="message-form"><input class="input" id="message" aria-label="Message" placeholder="Write a message…" maxlength="4000" required value="${esc(messageDraft)}"><button class="btn primary" type="submit">Send ${icon('arrow')}</button></form></div>`}</section>`;}
function nutrition(){if(role==='coach')return title('Fuel the training.','Nutrition sharing is a separate permission.')+`<section class="card pad"><h2>Athlete food logging is ready.</h2><p class="muted" style="margin:15px 0;font-size:13px">Athletes can record meals and macros in their workspace. Coach-issued targets and shared nutrition summaries are planned for the next release.</p><div class="notice">Food records remain private to the athlete in this foundation. Switch to Athlete view in the sample workspace to try logging.</div></section>`;
  const n=data.nutrition[dateKey()] || {entries:[],revision:0}, cals=n.entries.reduce((s,e)=>s+e.calories,0),macro=k=>n.entries.reduce((s,e)=>s+e[k],0);
  return title('Fuel your next session.','A simple daily log. Add what you ate, keep the context.',button('Log food','food','',true))+`<div class="grid two-col"><section class="card pad"><div class="row between"><h2>Today’s intake</h2><span class="date-chip">${dateKey()}</span></div><div class="nutrition-ring" style="--progress:100%"><div><strong>${num(cals)}</strong><small>calories logged</small></div></div><div class="grid" style="grid-template-columns:repeat(3,1fr);text-align:center"><div><h2>${num(macro('protein'))}g</h2><small>Protein</small></div><div><h2>${num(macro('carbs'))}g</h2><small>Carbs</small></div><div><h2>${num(macro('fat'))}g</h2><small>Fat</small></div></div><p class="footer-note">Values are entered by you. No calorie target has been assigned.</p></section><section class="card"><div class="card-head"><h2>Food log</h2>${badge(`${n.entries.length} entries`,'gray')}</div>${n.entries.map(e=>`<div class="checkin row between"><div><strong>${esc(e.name)}</strong><p style="margin:5px 0 0">${num(e.protein)}g protein · ${num(e.carbs)}g carbs · ${num(e.fat)}g fat</p></div><span>${num(e.calories)} kcal</span></div>`).join('')||empty('Your first meal is a good place to start.',button('Log food','food'))}</section></div>`;
}
function checkins(){const rels=activeRelations(), list=data.checkIns.filter(c=>rels.some(r=>r.id===c.relationshipId)).sort((a,b)=>b.createdAt-a.createdAt);return title('More than the numbers.',role==='coach'?'See how training feels. Give feedback that moves things forward.':'Share how you’re feeling and what your coach should know.',role==='athlete'&&rels.some(r=>r.consent.checkIns)?button('Submit check-in','checkin','',true):'')+`<section class="card">${list.map(c=>{const r=rels.find(r=>r.id===c.relationshipId);return `<div class="checkin"><div class="row between"><div class="row"><span class="avatar">${esc(initials(r.athleteName))}</span><div><h3>${esc(r.athleteName)}</h3><small>${when(c.createdAt)}</small></div></div>${badge(c.status,c.status==='reviewed'?'':'amber')}</div><p>${num(c.weightKg)} kg · Energy ${c.energy}/5</p><p>${esc(c.notes || 'No additional notes.')}</p>${c.feedback?`<div class="notice" style="margin-bottom:0">Coach feedback: ${esc(c.feedback)}</div>`:role==='coach'?button('Leave feedback','review',c.id):'<small>Your coach will review this check-in.</small>'}</div>`;}).join('')||empty('Check-ins will appear here once submitted.')}</section>`;}
function settings(){return title('Your workspace. Your rules.','Account, connections, and your data.')+`<section class="card pad"><h2>Account & data</h2><div class="setting-line"><div><strong>Connection</strong><p>${mode==='demo'?'Sample workspace. No data is sent to Firebase.':`Firebase project: ${esc(config.firebase.projectId)}`}</p></div>${badge(mode==='demo'?'Device only':'Firebase',mode==='demo'?'amber':'')}</div><div class="setting-line"><div><strong>Device outbox</strong><p>${data.outbox.length} pending changes${data.outbox[0]?.error?' · '+esc(data.outbox[0].error):''}. Kept until the server acknowledges them.</p></div>${button('Retry sync','sync')}</div><div class="setting-line"><div><strong>Export your data</strong><p>Download this device’s coaching data and unsent changes as JSON.</p></div>${button('Export','export')}</div>${mode==='firebase'&&!data.coachAccount?`<div class="setting-line"><div><strong>Coach access</strong><p>Administrator approval is required. Activate after your account is approved.</p></div>${button('Activate coach','activate-coach')}</div>`:''}<div class="setting-line"><div><strong>Original workout tracker</strong><p>The existing tracker is preserved alongside this workspace.</p></div><a class="btn" href="index.html">Open tracker ${icon('arrow')}</a></div>${mode==='firebase'?`<div class="setting-line"><div><strong>Sign out</strong><p>Signing out clears this account’s local coaching cache after synchronization.</p></div>${button('Sign out','signout')}</div>`:''}</section><section class="card pad section-space"><h2>Coaching connections</h2>${activeRelations().map(r=>`<div class="setting-line"><div><strong>${esc(role==='coach'?r.athleteName:r.coachName)}</strong><p>Workouts shared${r.consent.checkIns?' · Check-ins shared':''}</p></div>${button('End connection','end-relationship',r.id)}</div>`).join('')||'<p class="subtext">No active coaching connection.</p>'}</section><p class="footer-note">Foundation release: attachments, push notifications, historical workout correction, recurring schedules, and coach nutrition targets are not enabled yet.</p>`;}

function showModal(name,subtitle,body,form=''){modal.innerHTML=`<div class="dialog-top"><h2>${name}</h2><button aria-label="Close dialog" data-action="close-modal">×</button></div><p class="dialog-sub">${subtitle}</p>${form?`<form id="${form}">`:''}${body}<p id="form-error" class="error" role="alert"></p>${form?'</form>':''}`;if(!modal.open)modal.showModal();}
function actions(label){return `<div class="dialog-actions"><button type="button" class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${label}</button></div>`;}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function inviteModal(){showModal('Make the connection.','Invite an athlete to train with you.',`${mode==='demo'?'<div class="notice amber">Sample mode: this creates a local preview invitation, not a real coaching connection.</div>':''}${field('Athlete email','email','email','','required maxlength="254"')}<p class="subtext">Single use · Expires in 7 days · Athlete verifies their email and chooses what to share. No email is sent automatically.</p>${actions('Create invitation')}`,'invite-form');}
function builder(p){draft=structuredClone(p || {id:uuid(),name:'',description:'',workouts:[sampleWorkout('Workout A')],revision:0});draftWorkout=0;renderBuilder();}
function renderBuilder(){const w=draft.workouts[draftWorkout];showModal(draft.revision?'Refine the program.':'Build the next block.','Save a draft or publish an immutable version.',`${field('Program name','program-name','text',draft.name,'required maxlength="100"')}<div class="field"><label for="program-description">Description</label><textarea id="program-description" maxlength="1000">${esc(draft.description)}</textarea></div><div class="workout-tabs">${draft.workouts.map((w,i)=>`<button type="button" class="${i===draftWorkout?'active':''}" data-action="builder-tab" data-index="${i}">${esc(w.name)}</button>`).join('')}<button type="button" data-action="add-workout">+ Workout</button></div>${field('Workout name','workout-name','text',w.name,'required maxlength="100"')}${w.exercises.map((e,i)=>`<div class="builder-ex">${field('Exercise','exercise-'+i,'text',e.name,`data-builder-ex="${i}" required maxlength="100"`)}<div class="fields">${field('Sets','sets-'+i,'number',e.sets.length,`data-builder-count="${i}" min="1" max="12" required`)}${field('Reps','reps-'+i,'number',e.sets[0].reps,`data-builder-reps="${i}" min="0" max="1000" required`)}${field('Load · kg','load-'+i,'number',e.sets[0].weightKg,`data-builder-load="${i}" min="0" max="1000" step="0.5" required`)}</div><button type="button" class="btn small ghost danger" style="margin-top:10px" data-action="remove-builder-ex" data-index="${i}">Remove exercise</button></div>`).join('')}<button type="button" class="btn" data-action="add-exercise">+ Add exercise</button><p class="subtext">Assign the published version to an athlete from Programs. Existing assignments keep their original prescription.</p><div class="dialog-actions"><button class="btn" type="submit" name="intent" value="save">Save draft</button><button class="btn primary" type="submit" name="intent" value="publish">Publish version</button></div>`,'program-form');}
function collectBuilder(){if(!draft)return;draft.name=$('#program-name')?.value||draft.name;draft.description=$('#program-description')?.value||'';const w=draft.workouts[draftWorkout];w.name=$('#workout-name')?.value||w.name;w.exercises.forEach((e,i)=>{e.name=$('#exercise-'+i)?.value||e.name;const count=Number($('#sets-'+i)?.value||e.sets.length), reps=Number($('#reps-'+i)?.value??e.sets[0].reps),weightKg=Number($('#load-'+i)?.value??e.sets[0].weightKg);if(Number.isInteger(count)&&count>=1&&count<=12)e.sets=Array.from({length:count},(_,j)=>({id:e.sets[j]?.id||uuid(),reps,weightKg}));});}
function assignModal(pid){const rels=activeRelations();if(!rels.length){toast('Connect an athlete before assigning a program.');return;}showModal('Give the work a home.','A published snapshot will be copied into the athlete’s schedule.',`<input type="hidden" name="programId" value="${esc(pid)}"><div class="field"><label for="assign-athlete">Athlete</label><select id="assign-athlete" name="relationshipId">${rels.map(r=>`<option value="${esc(r.id)}">${esc(r.athleteName)}</option>`).join('')}</select></div>${field('First workout date','startDate','date',dateKey(),'required')}<p class="subtext">This release assigns one block, with workouts spaced two days apart. Publishing later versions does not alter this block.</p>${actions('Assign program')}`,'assign-form');}
function foodModal(){showModal('Fuel, logged.','Enter the nutrition values for one meal or food.',`${field('Food or meal','name','text','','required maxlength="100"')}<div class="fields">${field('Calories · kcal','calories','number','','required min="0" max="10000"')}${field('Protein · g','protein','number','0','required min="0" max="1000" step="0.1"')}${field('Carbs · g','carbs','number','0','required min="0" max="1000" step="0.1"')}${field('Fat · g','fat','number','0','required min="0" max="1000" step="0.1"')}</div>${actions('Save food')}`,'food-form');}
function checkinModal(){const r=getRelation();if(!r?.consent.checkIns){toast('Check-in sharing is not enabled.');return;}showModal('How’s the week feeling?','Give your coach the context behind the numbers.',`${field('Bodyweight · kg','weightKg','number','','required min="20" max="400" step="0.1"')}<div class="field"><label for="energy">Energy</label><select id="energy" name="energy">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n} / 5</option>`).join('')}</select></div><div class="field"><label for="notes">Anything your coach should know?</label><textarea id="notes" name="notes" maxlength="4000" placeholder="Training, recovery, sleep, wins…"></textarea></div>${actions('Submit check-in')}`,'checkin-form');}

function upsert(list,value){const i=list.findIndex(v=>v.id===value.id);if(i<0)list.push(value);else list[i]={...list[i],...value};}
function apply(action,p,result={}){
  const uid=currentUid();
  if(action==='saveProgram'||action==='publishProgram'){const clean=program(p);upsert(data.programs,{...p,...clean,coachId:uid,revision:p.expectedRevision+1,status:action==='publishProgram'?'published':'draft',publishedVersionId:action==='publishProgram'?`v${p.expectedRevision+1}`:p.publishedVersionId,publishedSnapshot:action==='publishProgram'?structuredClone(clean):p.publishedSnapshot,...result});}
  if(action==='assignProgram'&&mode==='demo'){const pr=data.programs.find(x=>x.id===p.programId), r=data.relationships.find(x=>x.id===p.relationshipId);(pr.publishedSnapshot||pr).workouts.forEach((w,i)=>{const date=new Date(`${p.startDate}T00:00:00`);date.setDate(date.getDate()+i*2);data.scheduled.push({id:uuid(),athleteId:r.athleteId,relationshipId:r.id,workout:structuredClone(w),programVersionId:pr.publishedVersionId,prescriptionRevision:1,status:'planned',scheduledLocalDate:dateKey(date)});});}
  if(action==='saveSession'){const old=data.sessions.find(s=>s.id===p.id), next=Object.keys(result).length?result:sessionUpdate(old,p,p.expectedRevision);upsert(data.sessions,{...p,...next,athleteId:uid,completedAt:p.status==='completed'?(result.completedAt||Date.now()):null});if(p.status==='completed'){data.activeSessionId=null;const s=data.scheduled.find(s=>s.id===p.scheduledId);if(s)s.status='completed';}}
  if(action==='sendMessage')upsert(data.messages,{...p,senderId:uid,createdAt:Date.now(),pending:mode==='firebase'});
  if(action==='saveNutrition')data.nutrition[p.date]={...p,revision:p.expectedRevision+1,...result};
  if(action==='submitCheckIn')upsert(data.checkIns,{...p,athleteId:uid,status:'submitted',createdAt:Date.now()});
  if(action==='reviewCheckIn'){const c=data.checkIns.find(c=>c.id===p.id);if(c)Object.assign(c,{status:'reviewed',feedback:p.feedback});}
  if(action==='revokeInvitation'){const i=data.invitations.find(i=>i.inviteId===p.inviteId);if(i)i.status='revoked';}
  if(action==='endRelationship'){const r=data.relationships.find(r=>r.id===p.relationshipId);if(r)r.status='ended';}
}
async function mutate(action,p,{offline=false}={}){
  const requestId=uuid();
  if(mode==='demo'){apply(action,p);await store();return {};}
  if(offline){
    const before=structuredClone(data);
    try{apply(action,p);data.outbox.push({requestId,action,data:p,uid:user.uid,createdAt:Date.now()});await store();}
    catch(e){data=before;throw e;}
    void sync(); return {};
  }
  if(!navigator.onLine)throw new Error('This action needs an internet connection.');
  const result=await api.call(action,p,requestId);apply(action,p,result);await store();return result;
}
async function sync(){
  if(mode!=='firebase'||!api||!user||!navigator.onLine||syncing||!data?.outbox.length)return;
  syncing=true;const owner=user.uid, ownerAccount=account, generation=authGeneration;
  try{
    while(data.outbox.length && user?.uid===owner && generation===authGeneration){
      const item=data.outbox[0];if(item.uid!==owner)throw new Error('Account mismatch. Export your data and sign in to the original account.');
      try{
        const result=await api.call(item.action,item.data,item.requestId);
        if(account!==ownerAccount||authGeneration!==generation)break;
        if(item.action==='saveSession'){const local=data.sessions.find(s=>s.id===item.data.id);if(local?.revision===result.revision)upsert(data.sessions,result);}
        if(item.action==='sendMessage'){const msg=data.messages.find(m=>m.id===item.data.id);if(msg)msg.pending=false;}
        data.outbox.shift();await store();
      }catch(e){if(authGeneration!==generation)break;item.error=e.message;await store();break;}
    }
  }catch(e){toast(e.message);}finally{syncing=false;render();}
}
async function startSession(scheduled){
  const active=data.sessions.find(s=>s.id===data.activeSessionId&&s.status==='inProgress'&&s.athleteId===currentUid());
  if(active){route='workouts';render();return;}
  const w=structuredClone(scheduled?.workout||sampleWorkout('Personal · Full body'));
  const p={...w,id:uuid(),scheduledId:scheduled?.id||null,relationshipId:scheduled?.relationshipId||null,status:'inProgress',localDate:dateKey(),expectedRevision:0,exercises:w.exercises.map(e=>({...e,sets:e.sets.map(s=>({...s,done:false}))}))};
  await mutate('saveSession',p,{offline:true});data.activeSessionId=p.id;await store();route='workouts';render();
}
async function saveActive(change){const s=data.sessions.find(s=>s.id===data.activeSessionId);if(!s)throw new Error('No active workout.');const p={...structuredClone(s),...change,expectedRevision:s.revision};await mutate('saveSession',p,{offline:true});}

document.addEventListener('click',async event=>{
  const b=event.target.closest('button,[data-route]');if(!b)return;
  if(b.dataset.route){route=b.dataset.route;filter='all';render();return;}
  if(b.dataset.filter){filter=b.dataset.filter;render();return;}
  const action=b.dataset.action, target=b.dataset.id;if(!action)return;
  try{
    if(action==='close-modal'){modal.close();return;}
    if(action==='invite')inviteModal();
    if(action==='new-program')builder();
    if(action==='edit-program')builder(data.programs.find(p=>p.id===target));
    if(action==='assign')assignModal(target);
    if(action==='add-workout'){collectBuilder();if(draft.workouts.length>=10)throw new Error('Use up to 10 workouts.');draft.workouts.push(sampleWorkout(`Workout ${String.fromCharCode(65+draft.workouts.length)}`));draftWorkout=draft.workouts.length-1;renderBuilder();}
    if(action==='builder-tab'){collectBuilder();draftWorkout=Number(b.dataset.index);renderBuilder();}
    if(action==='add-exercise'){collectBuilder();const w=draft.workouts[draftWorkout];if(w.exercises.length>=20)throw new Error('Use up to 20 exercises.');w.exercises.push({id:uuid(),name:'New exercise',sets:Array.from({length:3},()=>({id:uuid(),reps:10,weightKg:0}))});renderBuilder();}
    if(action==='remove-builder-ex'){collectBuilder();draft.workouts[draftWorkout].exercises.splice(Number(b.dataset.index),1);renderBuilder();}
    if(action==='quick-workout')await startSession();
    if(action==='start-workout')await startSession(data.scheduled.find(s=>s.id===target));
    if(action==='toggle-set'){const s=structuredClone(data.sessions.find(s=>s.id===data.activeSessionId));const set=s.exercises[Number(b.dataset.ex)].sets[Number(b.dataset.set)];set.done=!set.done;await saveActive({exercises:s.exercises});render();}
    if(action==='finish-workout'){const s=data.sessions.find(s=>s.id===target);if(!totals(s).sets)throw new Error('Complete at least one set before finishing.');const remaining=s.exercises.reduce((n,e)=>n+e.sets.filter(s=>!s.done).length,0);showModal('Finish this session?',`${totals(s).sets} completed sets · ${num(totals(s).volumeKg)} kg logged.`,`${remaining?`<div class="notice amber">${remaining} unchecked sets will remain uncompleted.</div>`:''}<p class="subtext">Completed workout records are locked in this release.</p><div class="dialog-actions">${button('Keep training','close-modal')}${button('Save completed workout','confirm-finish',target,true)}</div>`);}
    if(action==='confirm-finish'){await saveActive({status:'completed'});modal.close();filter='history';render();toast(mode==='demo'?'Workout saved on this device.':'Workout saved. Sync continues in the background.');}
    if(action==='athlete-detail'){const r=data.relationships.find(r=>r.id===target);showModal(esc(r.athleteName),'Your coaching connection.',`<div class="notice">${r.consent.workouts?'Workout sharing enabled.':''} ${r.consent.checkIns?'Check-in sharing enabled.':''}</div><p class="subtext">${data.sessions.filter(s=>s.relationshipId===r.id&&s.status==='completed').length} completed workouts loaded.</p><div class="dialog-actions">${button('Message athlete','open-message',r.id,true)}</div>`);}
    if(action==='conversation'||action==='open-message'){selectedRelation=target;messageDraft='';route='messages';modal.close();render();}
    if(action==='food')foodModal();
    if(action==='checkin')checkinModal();
    if(action==='review'){const c=data.checkIns.find(c=>c.id===target);showModal('A useful next step.','Your feedback will be shared with the athlete.',`<input name="id" type="hidden" value="${esc(c.id)}"><div class="field"><label for="feedback">Feedback</label><textarea id="feedback" name="feedback" required maxlength="4000"></textarea></div>${actions('Send feedback')}`,'review-form');}
    if(action==='go-workouts'){route='workouts';render();}
    if(action==='go-checkins'){route='checkins';render();}
    if(action==='sync'){await sync();toast(mode==='demo'?'Sample data is saved on this device.':data.outbox.length?'Changes are still pending. Check the connection or error above.':'All device changes are synchronized.');}
    if(action==='export'){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),mode,account,data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`flames-coaching-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    if(action==='revoke-invite'){await mutate('revokeInvitation',{inviteId:target});render();toast('Invitation revoked.');}
    if(action==='end-relationship'){showModal('End this coaching connection?','New messages and coach access will stop. Athlete workout history is retained.',`<p class="subtext">Previously downloaded information cannot be recalled.</p><div class="dialog-actions">${button('Keep connection','close-modal')}${button('End connection','confirm-end',target)}</div>`);}
    if(action==='confirm-end'){await mutate('endRelationship',{relationshipId:target});modal.close();render();toast('Coaching connection ended.');}
    if(action==='signin')await api.signIn();
    if(action==='activate-coach'){await mutate('onboard',{displayName:data.profile?.displayName||user.displayName||'Coach',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,coach:true});toast('Coach access activated.');}
    if(action==='signout'){if(data.outbox.length)throw new Error('Sync your pending changes before signing out. Export a backup if synchronization needs attention.');await api.signOut();}
    if(action==='copy-link'){await navigator.clipboard.writeText($('#invite-link').value);toast('Invitation link copied.');}
    if(action==='join')joinModal();
  }catch(e){if(modal.open && $('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}
});
document.addEventListener('change',async event=>{
  const t=event.target;
  if(t.id==='role'){role=t.value;route='dashboard';data.activeSessionId=data.sessions.find(s=>s.status==='inProgress'&&s.athleteId===currentUid())?.id||null;render();return;}
  if(t.dataset.sessionField){
    try{const value=Number(t.value);if(!Number.isFinite(value)||value<0||value>1000)throw new Error('Enter a value from 0 to 1000.');const s=structuredClone(data.sessions.find(s=>s.id===data.activeSessionId));s.exercises[Number(t.dataset.ex)].sets[Number(t.dataset.set)][t.dataset.sessionField]=value;await saveActive({exercises:s.exercises});}
    catch(e){toast(e.message);render();}
  }
});
document.addEventListener('input',event=>{if(event.target.id==='message')messageDraft=event.target.value;});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;if(!form.reportValidity())return;
  const p=Object.fromEntries(new FormData(form)),submit=event.submitter;if(submit)submit.disabled=true;
  try{
    if(form.id==='invite-form'){
      let result;
      if(mode==='demo')result={inviteId:uuid(),token:uuid(),expiresAt:Date.now()+7*86400000};
      else result=await mutate('createInvitation',{email:p.email});
      if(!result.token)throw new Error('The invitation was created but its token is unavailable. Create a new invitation.');
      data.invitations.push({...result,token:undefined,email:p.email,status:'pending'});await store();
      const url=new URL('coaching.html',location.href);url.hash=`invite=${result.token}`;
      showModal(mode==='demo'?'Preview invitation created.':'Invitation ready.','Share this link directly with the intended athlete.',`${mode==='demo'?'<div class="notice amber">Local preview only. This link cannot connect real accounts.</div>':''}${field('Invitation link','invite-link','text',url.href,'readonly')}<div class="dialog-actions">${button('Copy link','copy-link','',true)}</div>`);render();
    }
    if(form.id==='program-form'){collectBuilder();program(draft);const publish=event.submitter?.value==='publish';await mutate(publish?'publishProgram':'saveProgram',{...draft,expectedRevision:draft.revision});modal.close();route='programs';render();toast(publish?'Version published. Ready to assign.':'Draft saved.');}
    if(form.id==='assign-form'){await mutate('assignProgram',p);modal.close();render();toast('Program assigned. The athlete’s schedule will update.');}
    if(form.id==='message-form'){const r=getRelation();await mutate('sendMessage',{id:uuid(),relationshipId:r.id,text:p.message||$('#message').value},{offline:true});messageDraft='';render();}
    if(form.id==='food-form'){const date=dateKey(),n=data.nutrition[date]||{entries:[],revision:0};await mutate('saveNutrition',{date,entries:[...n.entries,{id:uuid(),name:p.name,calories:Number(p.calories),protein:Number(p.protein),carbs:Number(p.carbs),fat:Number(p.fat)}],expectedRevision:n.revision},{offline:true});modal.close();render();toast('Food saved.');}
    if(form.id==='checkin-form'){await mutate('submitCheckIn',{id:uuid(),relationshipId:getRelation().id,weightKg:Number(p.weightKg),energy:Number(p.energy),notes:p.notes},{offline:true});modal.close();render();toast('Check-in saved for your coach.');}
    if(form.id==='review-form'){const c=data.checkIns.find(c=>c.id===p.id);await mutate('reviewCheckIn',{...p,relationshipId:c.relationshipId});modal.close();render();toast('Feedback saved.');}
    if(form.id==='join-form'){if(mode==='demo')throw new Error('Real invitations require Firebase mode.');await mutate('acceptInvitation',{token:pendingInvite,consent:{workouts:true,nutrition:false,checkIns:p.checkIns==='on'}});pendingInvite=null;modal.close();toast('You’re connected. Your coach can now assign training.');}
  }catch(e){if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}
});

// Remove the bearer token from browser history immediately and keep it in memory.
let pendingInvite=new URLSearchParams(location.hash.slice(1)).get('invite');
if(pendingInvite)history.replaceState(null,'',location.pathname+location.search);
async function joinModal(){
  try{
    const preview=mode==='firebase'?await api.call('previewInvitation',{token:pendingInvite},uuid()):null;
    showModal('Connect with your coach.',preview?`Invitation from ${esc(preview.coachName)} for ${esc(preview.email)}.`:'The invitation is tied to your verified email address.',`${mode==='demo'?'<div class="notice amber">This workspace is not connected to Firebase. A real invitation cannot be accepted here.</div>':''}<p class="subtext">Accepting shares your assigned workout results with the inviting coach. End the connection anytime in Settings.</p><label class="consent"><input type="checkbox" checked required disabled> Share workouts (required)</label><label class="consent"><input type="checkbox" name="checkIns" checked> Share check-ins and submitted bodyweight</label><p class="subtext">Nutrition remains private. A single active primary coach is supported.</p>${actions('Accept invitation')}`,'join-form');
  }catch(e){showModal('Invitation unavailable.','Your coaching connection has not changed.',`<p class="error">${esc(e.message)}</p><div class="dialog-actions">${button('Close','close-modal')}</div>`);}
}
function renderLogin(){
  $('#app').innerHTML=`<main class="blank-onboarding"><a class="brand" href="coaching.html">${flame}<div><strong>FLAMES</strong><small>COACHING</small></div></a><div class="eyebrow">TRAINING, CONNECTED.</div><h1>A stronger you.<br>One day at a time.</h1><p class="muted">Your coach, your program, and your progress. One focused space to keep moving forward.</p><div style="margin-top:25px">${button('Continue with Google','signin','',true)}</div>${pendingInvite?'<div class="notice">Your invitation is ready. Sign in using the email your coach invited, then accept it.</div>':''}<p class="footer-note">Secure accounts powered by Firebase. Your coach’s access is controlled by your coaching connection.</p></main>`;
}
function blank(){return {schemaVersion:1,programs:[],relationships:[],sessions:[],scheduled:[],messages:[],checkIns:[],nutrition:{},outbox:[],invitations:[],activeSessionId:null};}
function watchError(e){toast(e.message || 'Unable to refresh cloud data. Your local changes are retained.');}
function mergeCloud(key,records,scope){
  const pendingIds=new Set(data.outbox.filter(o=>o.action==='saveSession'||o.action==='sendMessage'||o.action==='submitCheckIn').map(o=>o.data.id));
  const retained=data[key].filter(v=>!scope(v)||pendingIds.has(v.id));
  for(const value of records)if(!pendingIds.has(value.id))retained.push(value);
  data[key]=retained;void store();render();
}
function attachRelationship(r){
  if(relationSubscriptions.has(r.id))return;
  const unsubs=[],coach=r.coachId===user.uid;
  const watch=(path,filters,key,annotate)=>unsubs.push(api.list(path,filters,records=>mergeCloud(key,records.map(v=>({...v,...annotate})),v=>v.relationshipId===r.id),watchError));
  watch(`relationships/${r.id}/messages`,[],'messages',{relationshipId:r.id});
  if(r.consent.checkIns)watch(`relationships/${r.id}/checkIns`,[],'checkIns',{relationshipId:r.id});
  if(coach&&r.consent.workouts){watch(`athletes/${r.athleteId}/sessions`,[['relationshipId','==',r.id]],'sessions',{athleteId:r.athleteId});watch(`athletes/${r.athleteId}/scheduledWorkouts`,[['relationshipId','==',r.id]],'scheduled',{athleteId:r.athleteId});}
  relationSubscriptions.set(r.id,unsubs);
}
async function signedIn(next){
  const generation=++authGeneration, priorAccount=account;
  api?.stop();relationSubscriptions.clear();relationQueries.clear();
  user=next;
  if(!next){if(priorAccount.startsWith('firebase:'))await deleteAccount(priorAccount);account='signed-out';data=blank();renderLogin();return;}
  account=`firebase:${config.firebase.projectId}:${next.uid}`;
  data=await loadAccount(account)||blank();if(generation!==authGeneration)return;
  role=data.coachAccount?.status==='active'?'coach':'athlete';render();
  const profilePath=`users/${next.uid}`;
  api.doc(profilePath,profile=>{data.profile=profile;void store();render();},watchError);
  api.doc(`coachAccounts/${next.uid}`,c=>{data.coachAccount=c;if(!c&&role==='coach')role='athlete';render();},watchError);
  for(const field of ['coachId','athleteId'])api.list('relationships',[[field,'==',next.uid]],records=>{
    relationQueries.set(field,records);const all=[...new Map([...relationQueries.values()].flat().map(r=>[r.id,r])).values()];data.relationships=all;
    for(const [rid,unsubs] of relationSubscriptions){const rel=all.find(r=>r.id===rid);if(rel?.status==='active')continue;unsubs.forEach(u=>u());relationSubscriptions.delete(rid);data.messages=data.messages.filter(m=>m.relationshipId!==rid);data.checkIns=data.checkIns.filter(c=>c.relationshipId!==rid);data.sessions=data.sessions.filter(s=>s.athleteId===next.uid||s.relationshipId!==rid);data.scheduled=data.scheduled.filter(s=>s.athleteId===next.uid||s.relationshipId!==rid);}
    all.filter(r=>r.status==='active').forEach(attachRelationship);void store();render();
  },watchError);
  api.list('programs',[['coachId','==',next.uid]],records=>{data.programs=records;void store();render();},watchError);
  for(const [collection,key] of [['sessions','sessions'],['scheduledWorkouts','scheduled']])api.list(`athletes/${next.uid}/${collection}`,[],records=>mergeCloud(key,records.map(v=>({...v,athleteId:next.uid})),v=>v.athleteId===next.uid),watchError);
  api.list(`athletes/${next.uid}/nutritionDays`,[],records=>{for(const record of records)if(!data.outbox.some(o=>o.action==='saveNutrition'&&o.data.date===record.date))data.nutrition[record.date]=record;void store();render();},watchError);
  try{await api.call('onboard',{displayName:next.displayName||'Athlete',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone},uuid());}catch(e){watchError(e);}
  if(pendingInvite)joinModal();void sync();
}
async function boot(){
  try{
    if(mode==='demo'){data=await loadAccount('demo')||seed();await store();render();if(pendingInvite)joinModal();}
    else{data=blank();renderLogin();const {connectFirebase}=await import('./firebase-client.mjs');api=await connectFirebase(next=>{queueMicrotask(()=>signedIn(next));});}
    if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
  }catch(e){$('#app').innerHTML=`<main class="blank-onboarding"><h1>Couldn’t open the workspace.</h1><p class="error" style="margin-top:20px">${esc(e.message)}</p><p class="subtext">Check device storage permissions and Firebase configuration, then reload.</p><a class="btn" href="coaching.html">Reload workspace</a></main>`;}
}
window.addEventListener('online',()=>{render();void sync();});window.addEventListener('offline',render);
await boot();
